# Ajustes a la solicitud de Arrendamiento (observaciones de Expansion/Juridico). Ejecutar desde la raiz del repo.
$ErrorActionPreference = 'Stop'
$b0 = ""
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'backend\src\routes\arrendamientos\solicitudes.js'), [Convert]::FromBase64String($b0))
$b1 = ""
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'backend\src\utils\arrSolicitudForm.js'), [Convert]::FromBase64String($b1))
$b2 = ""
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'frontend\src\pages\arrendamientos\DetalleSolicitudArrendamiento.jsx'), [Convert]::FromBase64String($b2))
$b3 = ""
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'frontend\src\pages\arrendamientos\NuevaSolicitudArrendamiento.jsx'), [Convert]::FromBase64String($b3))
Write-Host 'Listo. Haz git add -A; git commit; git push y espera el deploy de Render y GitHub Pages.'